export const ROLE_SCOPES = Object.freeze(["Organization","Country","Program","Cohort"]);
export const ALL_ROLES = Object.freeze(Object.keys(ROLE_PERMISSIONS));

export function canEnterprise(role, permission) {
  const permissions=ROLE_PERMISSIONS[role]||ROLE_PERMISSIONS.Visitor;
  return permissions.includes("*")||permissions.includes(permission);
}

const now=()=>new Date().toISOString();
const id=prefix=>`${prefix}-${globalThis.crypto?.randomUUID?.()||Date.now().toString(36)}`;
const esc=(value="")=>String(value).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const badge=(label,tone="")=>`<span class="tag ${tone}">${esc(label)}</span>`;
const status=(label)=>`<span class="status-dot ${/approved|verified|complete|ready/i.test(label)?"verified":/draft|prototype|target|planning/i.test(label)?"draft":"pending"}">${esc(label)}</span>`;
const button=(label,action,cls="",extra="")=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;

const baseRecord=(type, ownerId="local-passport")=>({
  id:id(type.toLowerCase().replace(/ /g,"-")), type, ownerId, organizationId:null, countryCode:null,
  programId:null, status:"Private Draft", visibility:"Private", createdAt:now(), updatedAt:now(), createdBy:ownerId,
  lastReviewedAt:null, reviewedBy:null, source:"Founder-provided draft", verificationStatus:"Unverified", version:1, auditHistory:[]
});

export const enterpriseDefaultState = Object.freeze({
  schemaVersion:ENTERPRISE_SCHEMA_VERSION, section:"home", workspaceTab:"Overview", role:"Visitor",
  featureFlags:{...ENTERPRISE_FEATURE_FLAGS}, lowBandwidth:false, syncStatus:"Local only", lastSavedAt:null, formDraft:{},
  passportPath:"", founderStep:1, ventures:[], activeVentureId:"", stageTasks:{}, costPlan:{country:"Liberia",city:"",businessType:"",legalStructure:"",founders:1,ownership:"Local",regulated:"No",operation:"Online",employees:0,trade:"No",ip:"No",payments:[]},
  registrationCase:null, bankingCase:null, fundingChecks:{}, mentorRequest:null, mentorProfiles:[], partnerOffers:[], costSources:[],
  evidence:[], documents:[], audit:[], publicPreview:false, retryQueue:[], dashboardRole:"Founder"
});

export function normaliseEnterpriseState(value={}) {
  const next={...enterpriseDefaultState,...value,featureFlags:{...ENTERPRISE_FEATURE_FLAGS,...(value.featureFlags||{})},costPlan:{...enterpriseDefaultState.costPlan,...(value.costPlan||{})},fundingChecks:{...(value.fundingChecks||{})}};
  next.schemaVersion=ENTERPRISE_SCHEMA_VERSION;
  next.section=ENTERPRISE_SECTIONS.some(([key])=>key===next.section)?next.section:"home";
  next.workspaceTab=typeof next.workspaceTab==="string"?next.workspaceTab:"Overview";
  next.role=ALL_ROLES.includes(next.role)?next.role:"Visitor";
  next.ventures=Array.isArray(next.ventures)?next.ventures.map(venture=>({...baseRecord("Enterprise"),...venture,visibility:venture.visibility||"Private",version:Number(venture.version)||1})).slice(0,25):[];
  next.audit=Array.isArray(next.audit)?next.audit.slice(-200):[];
  next.documents=Array.isArray(next.documents)?next.documents.slice(0,100):[];
  next.evidence=Array.isArray(next.evidence)?next.evidence.slice(0,100):[];
  return next;
}

export const EnterpriseRepository = {
  async save(state){
    const payload={...state,schemaVersion:ENTERPRISE_SCHEMA_VERSION,lastSavedAt:now(),syncStatus:navigator.onLine?"Saved on this device":"Offline draft"};
    try{localStorage.setItem("btc-enterprise-state-v1",JSON.stringify(payload));}catch(_){}
    if(window.BTCOffline)await window.BTCOffline.put("enterpriseDrafts",{localId:"enterprise-workspace",payload,schemaVersion:ENTERPRISE_SCHEMA_VERSION,syncStatus:payload.syncStatus});
    return payload;
  },
  async load(){
    let local={};try{local=JSON.parse(localStorage.getItem("btc-enterprise-state-v1")||"{}");}catch(_){}
    try{const saved=await window.BTCOffline?.get("enterpriseDrafts","enterprise-workspace");if(saved?.payload&&new Date(saved.updatedAt||0)>new Date(local.lastSavedAt||0))local=saved.payload;}catch(_){}
    return normaliseEnterpriseState(local);
  },
  async saveDocument(document){if(window.BTCOffline)await window.BTCOffline.put("enterpriseDocuments",{localId:document.id,payload:document,syncStatus:"Local Draft"});},
  async saveEvidence(evidence){if(window.BTCOffline)await window.BTCOffline.put("enterpriseEvidence",{localId:evidence.id,payload:evidence,syncStatus:"Local Draft"});}
};

export const EnterpriseAdapters = Object.freeze(Object.fromEntries(Object.entries(CONNECTOR_STATUS).map(([name,connectionState])=>[name,Object.freeze({name,connectionState,async execute(){throw new Error(`${name} is ${connectionState}. Use the manual review pathway.`);}})])));

