function mentorPanel(s,compact=false){return `<div>${compact?"":pageTitle("Human-confirmed matching","Mentor Network","Recommendations consider founder needs, sector, stage, country, language, availability, capacity, safeguarding, and conflicts.")}<section class="panel panel-pad"><div class="workspace-head"><div><div class="eyebrow">Matching queue</div><h2>No eligible verified mentor match yet.</h2><p>AI may recommend candidates; a human program manager confirms every assignment.</p></div>${status("Not assigned")}</div><div class="mentor-criteria">${["Founder needs","Sector","Stage","Country","Language","Availability","Conflict checks","Maximum active assignments"].map(x=>`<span>${x}</span>`).join("")}</div>${button("Request a human-reviewed match","enterprise-mentor-request","primary")}</section><section class="section panel panel-pad"><h2>Mentor profiles</h2><p class="section-copy">Create a private application draft. It is not published, verified, safeguarding-cleared, or assigned.</p><div class="form-grid"><label class="field"><span>Expertise / industry</span><input id="mentor-expertise" placeholder="Comma-separated"/></label><label class="field"><span>Business stages</span><input id="mentor-stages" placeholder="Idea, pilot, launch…"/></label><label class="field"><span>Countries / cultural experience</span><input id="mentor-countries"/></label><label class="field"><span>Languages</span><input id="mentor-languages"/></label><label class="field"><span>Availability / session format</span><input id="mentor-availability" placeholder="e.g. 2 hours monthly, phone or video"/></label><label class="field"><span>Maximum active assignments</span><input id="mentor-capacity" type="number" min="0" max="20" value="1"/></label><label class="field full-width"><span>Conflicts of interest</span><textarea id="mentor-conflicts" placeholder="Declare any actual or potential conflicts"></textarea></label></div>${button("Save private mentor-profile draft","enterprise-mentor-draft","primary")}<div class="audit-list">${(s.mentorProfiles||[]).length?s.mentorProfiles.map(profile=>`<div><span>${esc((profile.expertise||[]).join(", ")||"Expertise not set")}</span><strong>Private Draft</strong><small>Unverified · safeguarding clearance not reviewed · ${profile.maximumAssignments||0} assignment capacity</small></div>`).join(""):`<div class="empty-state"><h3>No mentor-profile drafts.</h3><p>Published mentor profiles require verification, safeguarding review where relevant, conflict checks, and consent.</p></div>`}</div></section><div class="legal-guidance">Session agendas, private notes, shared notes, actions, feedback, and escalation records are never public by default.</div></div>`;}
function mentorsView(s){return `<div class="enterprise-page">${mentorPanel(s)}</div>`;}

