const PAYMENT_ROWS=[["Liberia","Mobile money provider","LRD / USD"],["Ghana","Mobile money provider","GHS"],["Uganda","Mobile money provider","UGX"],["Eligible markets only","Stripe adapter","Provider currencies"],["Country-specific","Bank transfer","Local currency"]];
function bankingPanel(s,compact=false){return `<div>${compact?"":pageTitle("Preparation, not approval","Banking & Payments","Compare published requirements, prepare a private checklist, and understand which payment rails still need country and provider validation.")}<section class="grid grid-2"><article class="panel panel-pad"><div class="eyebrow">Banking readiness</div><h2>No provider records reviewed yet.</h2><p>Provider, account type, currencies, deposit, fees, identity and business documents, beneficial owners, address evidence, review process, source, date, and availability must be verified.</p><div class="checklist">${["Business structure confirmed","Registration evidence ready","Tax record ready","Authorized signatories known","Beneficial owners documented","Proof-of-address alternative reviewed"].map(x=>`<label><input type="checkbox"/>${x}</label>`).join("")}</div>${button("Create private banking case","enterprise-banking-case","primary")}</article><article class="panel panel-pad"><div class="eyebrow">Case status vocabulary</div><div class="status-cloud">${BANK_STATES.map(x=>badge(x,x==="Approved"?"green":"violet")).join("")}</div><div class="privacy-callout">Never store passwords, full account credentials, card numbers, PINs, security answers, or private keys.</div></article></section><section class="section panel panel-pad"><div class="workspace-head"><div><div class="eyebrow">Provider-agnostic orchestration</div><h2>Payment demonstration</h2><p>No live provider is configured. Demonstration states never represent real money.</p></div>${status("Prototype")}</div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Country</th><th>Provider / rail</th><th>Currency</th><th>Collection</th><th>Payout</th><th>Source</th></tr></thead><tbody>${PAYMENT_ROWS.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>Not configured</td><td>Not configured</td><td>Not reviewed</td></tr>`).join("")}</tbody></table></div><div class="status-cloud">${["Not configured","Prototype","Sandbox","Pending approval","Live","Temporarily unavailable"].map(x=>badge(x,x==="Live"?"green":"violet")).join("")}</div><h3>Normalized transaction lifecycle</h3><div class="status-cloud">${["Created","Pending authorization","Processing","Paid","Failed","Expired","Refunded","Partially refunded","Disputed","Settled","Reconciled"].map(x=>badge(x,"violet")).join("")}</div><p class="footer-note">Adapters are prepared for payment intents, signed webhook validation, idempotency, duplicate protection, receipts, refunds, reconciliation, currency rounding, restricted-fund accounting, provider references, and finance exports. Secrets remain server-side.</p>${button("Run payment demonstration","enterprise-payment-demo","primary")}</section></div>`;}
