const FUNDING_ITEMS=["Funding need","Use of funds","Requested amount","Founder contribution","Revenue model","Cost model","Cash-flow projection","Pilot evidence","Customer validation","Team readiness","Legal readiness","Banking readiness","Safeguards","SDG outcomes","Risk register","Pitch deck","Data room"];
function fundingScore(s){const complete=FUNDING_ITEMS.filter(item=>s.fundingChecks[item]).length;return Math.round(complete/FUNDING_ITEMS.length*100);}
function fundingChecklist(s,compact=false){const score=fundingScore(s);return `<div>${compact?"":pageTitle("Preparation, not a promise","Funding Readiness","An explainable checklist shows what is complete, what is missing, and where a human reviewer can override with a reason.")}<section class="panel panel-pad"><div class="funding-score"><div><span>READINESS SCORE</span><strong>${score}%</strong><small>Requirement completion · not funding eligibility</small></div><div class="progress-track"><div class="progress-fill" style="width:${score}%"></div></div>${status(score===100?"Review can be requested":"Preparing")}</div><div class="funding-grid">${FUNDING_ITEMS.map(item=>`<label><input type="checkbox" data-funding-check="${esc(item)}" ${s.fundingChecks[item]?"checked":""}/><span><strong>${item}</strong><small>${s.fundingChecks[item]?"Founder marked complete · reviewer not yet confirmed":"Missing information"}</small></span></label>`).join("")}</div>${button("Request human review","enterprise-funding-review","primary")}</section><div class="legal-guidance">“Funding Ready” never means funding guaranteed. AI cannot approve funding, determine eligibility, or disburse money.</div></div>`;}
function fundingView(s){return `<div class="enterprise-page">${fundingChecklist(s)}<div class="status-cloud">${["Exploring","Preparing","Review requested","Revision needed","Funding ready","Introduced to funder","Due diligence","Approved","Declined","Awarded","Disbursing","Closed","Suspended"].map(x=>badge(x,x==="Funding ready"?"green":"violet")).join("")}</div><section class="section panel panel-pad"><div class="eyebrow">Commitment options · configurable by program</div><h2>Skin in the game without a universal paywall.</h2><div class="enterprise-link-grid">${["Pay commitment fee","Request a hardship waiver","Apply for a scholarship","Use a sponsor voucher","Commit verified service hours","Save and decide later"].map(x=>`<button class="panel-soft" data-action="enterprise-placeholder-save">${x}<span>→</span></button>`).join("")}</div><p class="footer-note">No amount is configured. Payment never implies approval, eligibility, credential completion, or guaranteed success. Public SDG and learning resources remain free.</p></section><section class="section panel panel-pad portfolio-preview"><div class="eyebrow">Restricted foundation console · planning only</div><h2>Proposed $5 million program budget</h2><p class="section-copy">Planning budget—not verified funds. No committed, received, awarded, disbursed, or spent balances are recorded. Balances stay separated by legal and financial entity.</p><div class="grid grid-4 enterprise-kpis">${[["$5M","Planned"],["—","Funds received"],["—","Disbursements"],["—","Remaining balance"]].map(([v,l])=>`<article class="panel-soft"><strong>${v}</strong><span>${l}</span></article>`).join("")}</div><div class="status-cloud">${["Platform operator","Foundation","Country chapter","Incubator program","Individual enterprise","Fiscally sponsored mission","Commercial supplier","Funding partner"].map(x=>badge(x,"violet")).join("")}</div><div class="privacy-callout">Configurable high-value disbursements require two-person approval. Efficiency measures display only when actual supporting records exist.</div></section></div>`;}

function leadersView(){return `<div class="enterprise-page">${pageTitle("Program workspace","Liberia Next Gen Leaders — 200 Participant Goal","Linked to the preserved Next Generation Leaders mission record. 200 is a target, not an achieved participation count.")}<section class="leaders-banner panel"><div><span>TARGET</span><strong>200</strong><small>participants · planning goal</small></div><div class="progress-track"><div class="progress-fill" style="width:0%"></div></div><div><span>ACTUAL RECORDS</span><strong>0</strong><small>No outcome totals claimed</small></div></section><div class="grid grid-4 leader-ops">${[["Recruitment",["Application form","Eligibility","County","Age pathway","Education & employment","Skills","Motivation","Community need","Referral","Accessibility","Consent"]],["Selection",["Reviewer assignment","Rubric","Conflict declaration","Interview notes","Scoring","Waitlist","Accepted","Not selected","Scholarship","Cohort balancing"]],["Delivery",["Cohort","Learning group","Calendar","Attendance","Course assignments","Assessments","Mentor","Office hours","Peer team","Community challenge","Evidence","Credential progress"]],["Outcomes",["Applied","Eligible","Accepted","Enrolled","Active","Completed","Business planned","Business registered","Pilot launched","Revenue band","Jobs sustained","Community served","Funding received","Alumni mentor","Replication"]]].map(([title,items])=>`<article class="panel panel-pad"><h3>${title}</h3><ul>${items.map(i=>`<li>${i}</li>`).join("")}</ul></article>`).join("")}</div><section class="section panel panel-pad"><div class="eyebrow">Role dashboards</div><h2>Records, not invented totals.</h2><div class="role-dashboard-grid">${["Participant","Mentor","Country Coordinator","Program Manager"].map(r=>`<div><strong>${r}</strong><span>Empty state · next action configured</span></div>`).join("")}</div></section></div>`;}

const DOCUMENTS=["One-page concept","Community-need statement","Customer discovery report","Business model canvas","Lean canvas","Business plan","Startup budget","Cash-flow projection","Pricing model","Launch plan","Founder agreement","Operating agreement or bylaws template","Cap table","Registration checklist","Tax checklist","Supplier agreement","Customer agreement","Employment template","Privacy policy","Terms","Safeguarding plan","Environmental and social risk assessment","Pitch deck","Grant application","Due-diligence data room checklist"];
function toolsGrid(s,compact=false){return `<div>${compact?"":pageTitle("Guided documents","Business Tools","Each template is a starting point—not legal, tax, accounting, or investment advice.")}<div class="document-grid">${DOCUMENTS.map(name=>`<article class="panel${compact?"-soft":""}"><div><span class="document-icon">▤</span><div><strong>${name}</strong><small>Draft · private · version 1</small></div></div>${button("Create draft","enterprise-document","small",`data-document-name="${esc(name)}"`)}</article>`).join("")}</div></div>`;}
function toolsView(s){return `<div class="enterprise-page">${toolsGrid(s)}<section class="section grid grid-2"><article class="panel panel-pad"><div class="eyebrow">Responsible products · future record</div><h2>Sustainable product workspace</h2><p>Create reviewed records for reusable goods, including bamboo-based concepts, without asserting sustainability before evidence exists.</p><details class="panel-soft"><summary>Product record fields</summary><div class="status-cloud">${["Product name","Enterprise","Materials","Supplier","Manufacturer","Country of origin","Batch","Certifications","Certification evidence","Cost of goods","Wholesale price","Retail price","Inventory","Warehousing","Distribution","Quality control","Returns","End-of-life pathway","Environmental claims","Claim evidence","Availability","Commerce state"].map(x=>badge(x,"violet")).join("")}</div></details><div class="privacy-callout">Environmental and sustainability claims require approved evidence.</div></article><article class="panel panel-pad"><div class="eyebrow">Product passports</div><h2>Digital product identity</h2><p>Optional opaque QR or RFID identifiers can link product, batch, manufacturer, authenticity, distribution, care, recall, circular return, approved story, and approved evidence.</p><div class="privacy-callout">No private personal information is placed in an identifier. Manufacturing, inventory, and checkout remain unconnected.</div>${button("Create product-passport draft","enterprise-product-passport","primary")}</article></section><section class="section panel panel-pad"><div class="eyebrow">Operational trust</div><h2>Safeguards & responsible AI</h2><p>Private-by-default youth accounts, consent and guardian pathways, incident reporting, country-specific ages, KYC/KYB placeholders, fraud review, conflicts, anti-bribery controls, complaints, appeals, whistleblowing, retention, export, deletion requests, sensitive-access logs, grant restrictions, claim review, and environmental/social safeguards.</p><p class="section-copy">AI may explain, draft, summarize, recommend, identify gaps, generate checklists, flag inconsistencies, and prepare reviewer summaries. It cannot approve businesses, registrations, funding, disbursements, identity, safeguarding, impact claims, mentor assignments, or partner verification.</p>${status("Human decisions required")}</section></div>`;}

function impactPanel(s,compact=false){const states=["Target","Self-reported","Submitted","Under review","Verified","Disputed","Corrected","Withdrawn"];return `<div>${compact?"":pageTitle("Evidence-led","Enterprise Impact","Draft, demonstration, and unverified claims are excluded from verified totals.")}<section class="panel panel-pad"><div class="workspace-head"><div><div class="eyebrow">Verified enterprise results</div><h2>0 verified results</h2><p>Every future result carries a definition, unit, period, geography, source, evidence, reviewer, verification state, and correction history.</p></div>${badge("No fabricated totals","green")}</div><div class="status-cloud">${states.map(x=>badge(x,x==="Verified"?"green":"violet")).join("")}</div><div class="empty-state"><h3>No enterprise evidence has completed review.</h3><p>Submit evidence from a private workspace to begin a human review trail.</p>${button("Open evidence workspace","enterprise-workspace-tab","primary","data-workspace-tab=\"Evidence\"")}</div></section></div>`;}
